from lib import *
L = lambda *a, **k: lesson(27, "A0", *a, **k)
V = "verb"
A = "adjective"
L(1, "Заселення", "Заселитися в готель: назвати бронювання й отримати ключ.",
 "На рецепції: I have a booking — «у мене бронювання» (booking і reservation означають те саме). A single room — номер на одного, a double room — на двох. For three nights — на три ночі. Вас попросять назвати surname — прізвище.",
 [W("reception", "/rɪˈsepʃn/", "noun", "рецепція", "Go to reception.", "Ідіть на рецепцію."),
  W("booking", "/ˈbʊkɪŋ/", "noun", "бронювання", "I have a booking.", "У мене бронювання."),
  W("single room", "/ˌsɪŋɡl ˈruːm/", "noun", "номер на одного", "A single room, please.", "Номер на одного, будь ласка."),
  W("double room", "/ˌdʌbl ˈruːm/", "noun", "номер на двох", "A double room for two nights.", "Номер на двох на дві ночі."),
  W("surname", "/ˈsɜːneɪm/", "noun", "прізвище", "What's your surname?", "Яке ваше прізвище?"),
  W("key card", "/ˈkiː kɑːd/", "noun", "картка-ключ", "Here's your key card.", "Ось ваша картка-ключ.")],
 [li("What's the purpose of your visit?", "Повторимо. Ви у відпустці. Що відповісти?", ["I'm here on holiday.", "I'm here in holiday.", "My holiday is purpose."], "I'm here on holiday."),
  mt([("reception", "рецепція"), ("booking", "бронювання"), ("surname", "прізвище"), ("key card", "картка-ключ")], "Перші слова в готелі."),
  mt([("single room", "номер на одного"), ("double room", "номер на двох"), ("for two nights", "на дві ночі"), ("for a week", "на тиждень")], "For — на який час."),
  liu("I have a booking for three nights.", "Прослухайте. На скільки бронювання?", ["На три ночі", "На три дні", "На два тижні"], "For three nights."),
  liu("What's your surname, please?", "Прослухайте. Про що питають?", ["Про прізвище", "Про ім'я", "Про адресу"], "Surname — прізвище."),
  liu("Here's your key card. Room three hundred and four.", "Прослухайте. Який номер кімнати?", ["304", "314", "340"], "Three hundred and four — 304."),
  fb("I have a ___. My surname is Koval.", ["booking", "reception", "key card"], "I have a booking."),
  fb("A double room ___ two nights, please.", ["for", "on", "at"], "For two nights."),
  mcu("Ви подорожуєте самі. Який номер потрібен?", ["a single room", "a double room", "a waiting room"], "A single room."),
  bs("У мене бронювання на дві ночі.", ["I", "have", "a", "booking", "for", "two", "nights"], ["room"], "I have a booking for two nights."),
  tr("Номер на двох, будь ласка.", ["A double room, please"], "A double room, please."),
  li("Good evening. Do you have a booking?", "Бронювання є, прізвище Коваль. Що відповісти?", ["Yes, I do. My surname is Koval.", "Yes, I am. My surname Koval.", "Yes, I book Koval."], "Yes, I do. My surname is Koval.")])
L(2, "Ваш номер", "Розпитати про номер: поверх, сніданок, вайфай.",
 "Floor ви знаєте як «підлогу»; у будівлі це «поверх»: on the second floor. У Британії перший поверх називають ground floor, а first floor — це вже другий. Is breakfast included? — «Сніданок входить у ціну?». What's the Wi-Fi password? — «Який пароль від вайфаю?»",
 [W("floor", "/flɔː/", "noun", "поверх", "On the third floor.", "На третьому поверсі."),
  W("ground floor", "/ˌɡraʊnd ˈflɔː/", "noun", "перший поверх (на рівні землі)", "Reception is on the ground floor.", "Рецепція на першому поверсі."),
  W("included", "/ɪnˈkluːdɪd/", A, "включений у ціну", "Breakfast is included.", "Сніданок входить у ціну."),
  W("password", "/ˈpɑːswɜːd/", "noun", "пароль", "What's the password?", "Який пароль?"),
  W("view", "/vjuː/", "noun", "краєвид, вид", "A room with a view.", "Номер із гарним видом."),
  W("towel", "/ˈtaʊəl/", "noun", "рушник", "Clean towels.", "Чисті рушники.")],
 [fb("A single room ___ three nights, please.", ["for", "in", "to"], "For three nights.", "Повторимо. Оберіть слово, якого бракує"),
  mt([("floor", "поверх"), ("ground floor", "перший поверх"), ("included", "включений у ціну"), ("password", "пароль")], "On the ground floor, on the first floor."),
  mt([("view", "краєвид"), ("towel", "рушник"), ("lift", "ліфт"), ("key card", "картка-ключ")], "Що є в номері й готелі."),
  liu("Your room is on the fourth floor.", "Прослухайте. На якому поверсі номер?", ["На четвертому", "На чотирнадцятому", "На першому"], "The fourth floor."),
  liu("Is breakfast included?", "Прослухайте. Що питає гість?", ["Чи входить сніданок у ціну", "Коли сніданок", "Де сніданок"], "Included — входить у ціну."),
  liu("Breakfast is from seven to ten on the ground floor.", "Прослухайте. Де й коли сніданок?", ["На першому поверсі, з 7 до 10", "На другому поверсі, з 7 до 10", "У номері, о 7"], "On the ground floor, from seven to ten."),
  fb("What's the Wi-Fi ___?", ["password", "floor", "view"], "The Wi-Fi password."),
  fb("My room is ___ the second floor.", ["on", "in", "at"], "On the second floor."),
  mcu("У британському готелі вам кажуть first floor. Скільки поверхів треба піднятися?", ["Один", "Жодного", "Два"], "Ground floor — рівень землі, first floor — на один вище."),
  bs("Сніданок входить у ціну?", ["Is", "breakfast", "included"], ["does", "password"], "Is breakfast included?"),
  tr("Який пароль від вайфаю?", ["What's the Wi-Fi password", "What is the Wi-Fi password"], "What's the Wi-Fi password?"),
  li("Is there a lift?", "Ліфт є, біля рецепції. Що відповість працівник?", ["Yes, there is. It's next to reception.", "Yes, it is. Next reception.", "Yes, there are lift."], "Yes, there is. It's next to reception.")])
L(3, "Можна ще один рушник?", "Попросити в готелі додаткові речі.",
 "Could I have…? — найввічливіший спосіб попросити: Could I have an extra towel, please? Extra — «додатковий, ще один». Перед extra ставлять an, бо слово починається з голосного.",
 [W("extra", "/ˈekstrə/", A, "додатковий", "An extra towel.", "Додатковий рушник."),
  W("pillow", "/ˈpɪləʊ/", "noun", "подушка", "An extra pillow, please.", "Ще одну подушку, будь ласка."),
  W("blanket", "/ˈblæŋkɪt/", "noun", "ковдра", "Could I have a blanket?", "Можна мені ковдру?"),
  W("soap", "/səʊp/", "noun", "мило", "There's no soap.", "Немає мила."),
  W("hairdryer", "/ˈheədraɪə/", "noun", "фен", "Is there a hairdryer?", "Тут є фен?")],
 [li("Is breakfast included?", "Повторимо. Сніданок входить у ціну. Що відповість працівник?", ["Yes, it is.", "Yes, it does.", "Yes, it's include."], "Yes, it is."),
  mt([("extra", "додатковий"), ("pillow", "подушка"), ("blanket", "ковдра"), ("soap", "мило"), ("hairdryer", "фен")], "Речі, про які просять на рецепції."),
  liu("Could I have an extra pillow, please?", "Прослухайте. Що просить гість?", ["Ще одну подушку", "Ще одну ковдру", "Ще один рушник"], "An extra pillow."),
  liu("Is there a hairdryer in the room?", "Прослухайте. Що питає гість?", ["Чи є в номері фен", "Де фен", "Чи працює фен"], "Is there a hairdryer?"),
  mc("Як правильно?", ["an extra blanket", "a extra blanket", "an blanket extra"], "Extra — з голосного: an extra blanket."),
  mcu("Яке прохання найввічливіше?", ["Could I have a towel, please?", "I want a towel.", "Give me a towel."], "Could I have…, please?"),
  fb("Could I ___ an extra towel, please?", ["have", "do", "am"], "Could I have…?"),
  fb("It's cold. Could I have a ___?", ["blanket", "soap", "hairdryer"], "Від холоду — blanket."),
  fb("There's no ___ in the bathroom.", ["soap", "pillow", "blanket"], "У ванній — soap."),
  bs("Можна мені ще одну подушку?", ["Could", "I", "have", "an", "extra", "pillow"], ["a"], "Could I have an extra pillow?"),
  tr("Тут є фен?", ["Is there a hairdryer", "Is there a hairdryer here"], "Is there a hairdryer?"),
  li("Could I have two extra towels, please?", "Працівник згоден. Що він відповість?", ["Yes, of course.", "Yes, I could of.", "No problem not."], "Yes, of course.")])
L(4, "Щось не працює", "Повідомити про проблему в номері.",
 "Про зламану річ: The shower doesn't work — «душ не працює». Або: The lamp is broken — «лампа зламана». There's no… — «немає…»: There's no hot water. Якщо нічого не допомагає: Can I change rooms? — «Можна поміняти номер?»",
 [W("doesn't work", "/ˌdʌznt ˈwɜːk/", "phrase", "не працює", "The TV doesn't work.", "Телевізор не працює."),
  W("broken", "/ˈbrəʊkən/", A, "зламаний", "The lamp is broken.", "Лампа зламана."),
  W("there's no", "/ðeəz ˈnəʊ/", "phrase", "немає", "There's no hot water.", "Немає гарячої води."),
  W("heating", "/ˈhiːtɪŋ/", "noun", "опалення", "The heating doesn't work.", "Опалення не працює."),
  W("change rooms", "/ˌtʃeɪndʒ ˈruːmz/", "phrase", "поміняти номер", "Can I change rooms?", "Можна поміняти номер?")],
 [fb("Could I have ___ extra blanket, please?", ["an", "a", "some"], "An extra.", "Повторимо. Оберіть слово, якого бракує"),
  mt([("doesn't work", "не працює"), ("broken", "зламаний"), ("there's no", "немає"), ("heating", "опалення"), ("change rooms", "поміняти номер")], "Як сказати про проблему."),
  liu("The shower doesn't work.", "Прослухайте. Що не працює?", ["Душ", "Опалення", "Телевізор"], "The shower."),
  liu("There's no hot water in my room.", "Прослухайте. У чому проблема?", ["Немає гарячої води", "Немає холодної води", "Вода занадто гаряча"], "There's no hot water."),
  liu("My room is very noisy. Can I change rooms?", "Прослухайте. Чого хоче гість?", ["Поміняти номер", "Зачинити вікно", "Виїхати з готелю"], "Change rooms."),
  fb("The Wi-Fi ___ work.", ["doesn't", "don't", "isn't"], "The Wi-Fi — it: doesn't work."),
  fb("The window is ___. I can't close it.", ["broken", "included", "extra"], "Broken — зламане."),
  fb("___ no towel in the bathroom.", ["There's", "It's", "There are"], "There's no towel."),
  mc("Як правильно?", ["The heating doesn't work.", "The heating doesn't works.", "The heating not work."], "Doesn't + work."),
  bs("Телевізор не працює.", ["The", "TV", "doesn't", "work"], ["isn't", "works"], "The TV doesn't work."),
  tr("Немає гарячої води.", ["There's no hot water", "There is no hot water"], "There's no hot water."),
  li("Is everything OK with your room?", "У вас не працює опалення. Що відповісти?", ["No, the heating doesn't work.", "No, the heating don't work.", "Yes, the heating is broken."], "No, the heating doesn't work.")])
L(5, "Виселення", "Виселитися з готелю й залишити багаж.",
 "I'd like to check out — «я хотів би виселитися». What time is check-out? — «О котрій виселення?». Can I leave my luggage here? — «Можна залишити тут багаж?». На прощання в готелі кажуть Enjoy your stay — «гарного вам перебування» при заселенні, і Have a good trip — «гарної дороги» при від'їзді.",
 [W("check out", "/ˌtʃek ˈaʊt/", V, "виселятися", "I'd like to check out.", "Я хотів би виселитися."),
  W("enjoy your stay", "/ɪnˌdʒɔɪ jɔː ˈsteɪ/", "phrase", "гарного перебування", "Enjoy your stay!", "Гарного перебування!"),
  W("have a good trip", "/hæv ə ˌɡʊd ˈtrɪp/", "phrase", "гарної дороги", "Have a good trip!", "Гарної дороги!"),
  W("everything", "/ˈevriθɪŋ/", "pronoun", "усе", "Is everything OK?", "Усе гаразд?"),
  W("leave my luggage", "/ˌliːv maɪ ˈlʌɡɪdʒ/", "phrase", "залишити багаж", "Can I leave my luggage here?", "Можна залишити тут багаж?")],
 [li("Is everything OK with your room?", "Повторимо. Не працює душ. Що відповісти?", ["No, the shower doesn't work.", "No, the shower isn't work.", "Yes, there's no shower."], "No, the shower doesn't work."),
  mt([("check in", "заселятися"), ("check out", "виселятися"), ("everything", "усе"), ("leave my luggage", "залишити багаж")], "Check in і check out — початок і кінець перебування."),
  liu("What time is check-out?", "Прослухайте. Що питає гість?", ["О котрій виселення", "О котрій заселення", "О котрій сніданок"], "Check-out — виселення."),
  liu("Check-out is at eleven o'clock.", "Прослухайте. Коли виселення?", ["Об 11:00", "О 12:00", "О 7:00"], "Eleven o'clock."),
  liu("Can I leave my luggage here until three?", "Прослухайте. Чого хоче гість?", ["Залишити багаж до третьої", "Залишитися до третьої", "Забрати багаж о третій"], "Leave my luggage until three."),
  mcu("Вас заселили й кажуть Enjoy your stay! Що відповісти?", ["Thank you!", "You too!", "You're welcome!"], "Працівник у готелі не зупиняється, тому просто Thank you."),
  fb("I'd like to check ___, please. Room 210.", ["out", "off", "up"], "Check out."),
  fb("Is ___ OK? — Yes, thank you.", ["everything", "every", "extra"], "Is everything OK?"),
  fb("Can I ___ my luggage here?", ["leave", "live", "enjoy"], "Leave — залишити. Live — жити."),
  bs("Я хотів би виселитися.", ["I'd", "like", "to", "check", "out"], ["in", "off"], "I'd like to check out."),
  tr("О котрій виселення?", ["What time is check-out", "What time is the check-out"], "What time is check-out?"),
  li("Have a good trip!", "Вам бажають гарної дороги. Що відповісти?", ["Thank you! Goodbye.", "You're welcome! Goodbye.", "Enjoy your stay!"], "Thank you! Goodbye.")])
